int networkDelayTime(vector<vector<int>>& t, int n, int k) {
    vector<vector<pair<int,int>>> g(n + 1); for (auto& e : t) g[e[0]].push_back({e[1], e[2]});
    vector<long long> d(n + 1, LLONG_MAX); d[k] = 0; priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> h; h.push({0, k});
    while (!h.empty()) { auto [du, u] = h.top(); h.pop(); if (du > d[u]) continue; for (auto [v, w] : g[u]) if (du + w < d[v]) { d[v] = du + w; h.push({d[v], v}); } }
    long long m = *max_element(d.begin() + 1, d.end()); return m == LLONG_MAX ? -1 : (int)m;
}
